start.wrappers.py:
"""Wrappers for the Hutline price functions."""

LOG = []


def audit(fn):
    def wrapper(x):
        result = fn(x)
        LOG.append("audit:cap70")
        return min(result, 70)

    return wrapper


def metered(fn):
    def wrapper(x):
        result = fn(x)
        LOG.append("metered:+2")
        return result + 2

    return wrapper


def timed(fn):
    def wrapper(x):
        LOG.append("timed:x6")
        return fn(x * 6)

    return wrapper

