/** Builds one task per slot. */
function withVar(n) {
  var tasks = [];
  for (var i = 0; i < n; i++) {
    tasks.push(() => i * 2);
  }
  return tasks;
}

function withLet(n) {
  const tasks = [];
  for (let i = 0; i < n; i++) {
    tasks.push(() => i * 4);
  }
  return tasks;
}

function withIife(n) {
  const tasks = [];
  for (var i = 0; i < n; i++) {
    tasks.push(((slot) => () => slot + 100)(i));
  }
  return tasks;
}

