'use strict';

const LOG = [];

const audited = (fn) => (x) => {
  LOG.push('audited>');
  const out = fn(x);
  LOG.push('<audited');
  return out;
};

const metered = (fn) => (x) => {
  LOG.push('metered:x7');
  return fn(x * 7);
};

const doubled = (fn) => (x) => {
  const out = fn(x);
  LOG.push('doubled:+4');
  return out + 4;
};

const compose = (...fns) => (fn) => fns.reduceRight((acc, wrap) => wrap(acc), fn);

module.exports = { LOG, audited, metered, doubled, compose };

